// metPalette.js — 气象业务色阶（与 colormap.js 的科学色图**并列但性质不同**）
//
// turbo / viridis / inferno 那一族是「等感知步长的连续色带」，为的是让人分辨出细微差别；
// 气象业务色阶要的是另一件事 —— 让一张图**一眼看出天气**。三条差别，缺一条就不像云图：
//
//   ① 低值透明。云图里没下雨的地方是**透明的**，能看见底下的地表；不是被涂成 turbo 的深蓝。
//      这是「一个矩形色块」与「一片雨区」的全部差别。故每一档除 RGB 外还带 alpha。
//   ② 档位按业务量级，不按数值等分。降水是极长尾的量：一片场里 90% 的格在 0~1 mm/h，
//      而峰值能到 50。线性铺色会把主区压成一个颜色、把整条色带让给几个孤立的格子。
//      故走**锚点**（levels）：值轴不等距、色轴等距 —— 这正是气象业务色标的定义。
//   ③ 色相序沿「冷→暖→紫」走。这个序不是审美选择，是几十年雷达/降水图训练出来的读图直觉：
//      青绿=小、黄=中、红=大、紫/白=极端。换个好看的序，图就要重新学着读。
//
// ★ 与 alpha 的两层关系：这里的 alpha 是**逐像素**的（值越小越透明），
//   图层总透明度是另一层（渲染端 material.opacity / ctx.globalAlpha）。两者相乘，各管各的：
//   前者表达「这儿有没有天气」，后者表达「这层图压多重」。混成一个数就两件事都表达不了。

// 色阶定义：[u, r, g, b, a]，u ∈ [0,1] 升序，两端必须给全。
const STOPS = {
  // 降水 —— 雷达回波的色相序，饱和度略收，免得整张图像玩具。
  // 底部留一小段**全透明死区**：0 与「几乎是 0」都不该在图上留痕，否则整片区域蒙一层雾。
  precip: [
    [0.00, 150, 205, 255, 0],
    [0.05, 135, 205, 248, 0],
    [0.13, 120, 205, 240, 75],
    [0.24, 90, 205, 175, 155],
    [0.36, 90, 195, 95, 202],
    [0.48, 185, 215, 80, 225],
    [0.60, 245, 215, 75, 238],
    [0.72, 246, 160, 60, 246],
    [0.84, 238, 88, 60, 251],
    [0.93, 206, 45, 110, 253],
    [1.00, 150, 55, 180, 255]
  ],
  // 衰减 —— 与降水刻意不同族：读的是「链路劣化程度」不是「下多大雨」。
  // 顶端收到亮粉白而不是更红：极端值要与「很红」分得开，否则 8 dB 和 30 dB 在图上一个样。
  //
  // ★ 底部那段全透明死区（到 u=0.13）不是留白好看，是**必须的**：合计衰减有一个晴空底 ——
  //   气体吸收在任何地方任何时候都有 0.03~0.2 dB，全场无一格为零。低端一旦有 alpha，
  //   整张图就蒙一层灰蓝雾，而青藏高原（大气薄、气体吸收最小）反倒显成一个「白洞」，
  //   看着像缺数据。死区正好把这个晴空底吃掉，图上留下的才是天气造成的那部分。
  //   与字段的 levels 锚点是配套的：totalAtten 首档 0~0.2 dB 正是晴空底所在。
  atten: [
    [0.00, 45, 70, 130, 0],
    [0.13, 55, 105, 180, 0],
    [0.24, 70, 180, 195, 125],
    [0.40, 95, 200, 120, 195],
    [0.55, 225, 205, 80, 226],
    [0.70, 245, 150, 55, 242],
    [0.85, 235, 70, 55, 251],
    [1.00, 255, 190, 235, 255]
  ],
  // 云 —— 可见光云图：透明→白。压在真彩影像底图上就是那张图。
  cloudy: [
    [0.00, 245, 248, 255, 0],
    [0.12, 245, 248, 255, 22],
    [0.35, 246, 249, 255, 85],
    [0.60, 250, 252, 255, 150],
    [0.82, 253, 254, 255, 205],
    [1.00, 255, 255, 255, 240]
  ],
  // 红外增强 —— 灰白云顶 + 高端染色。气象台那张「强对流一块块变红」的图就是这个色表：
  // 云顶越高越冷 → 在本平台对应柱云水/云量的高端，正好落在染色段。
  cloudIr: [
    [0.00, 255, 255, 255, 0],
    [0.30, 235, 240, 248, 90],
    [0.55, 250, 252, 255, 175],
    [0.70, 255, 255, 255, 225],
    [0.80, 120, 215, 235, 238],
    [0.88, 70, 190, 110, 246],
    [0.94, 240, 215, 80, 251],
    [0.98, 240, 120, 60, 253],
    [1.00, 215, 55, 70, 255]
  ]
}

export const MET_SCHEMES = [
  { v: 'precip', label: '降水（业务）' },
  { v: 'atten', label: '衰减（业务）' },
  { v: 'cloudy', label: '云（可见光）' },
  { v: 'cloudIr', label: '云（红外增强）' }
]

export const isMetScheme = (name) => Object.prototype.hasOwnProperty.call(STOPS, name)

const lutCache = new Map()

/** 256 级 RGBA 查找表。invert=true 时整表倒序（含 alpha —— 反相后高值变透明，是用户自找的） */
export function metLut(name, invert) {
  const key = name + (invert ? '|i' : '')
  let lut = lutCache.get(key)
  if (lut) return lut
  const st = STOPS[name] || STOPS.precip
  lut = new Uint8Array(256 * 4)
  for (let i = 0; i < 256; i++) {
    const u = (invert ? 255 - i : i) / 255
    let k = 0
    while (k < st.length - 2 && u > st[k + 1][0]) k++
    const a = st[k], b = st[k + 1]
    const w = b[0] > a[0] ? (u - a[0]) / (b[0] - a[0]) : 0
    const t = w < 0 ? 0 : w > 1 ? 1 : w
    const p = i * 4
    lut[p] = a[1] + (b[1] - a[1]) * t
    lut[p + 1] = a[2] + (b[2] - a[2]) * t
    lut[p + 2] = a[3] + (b[3] - a[3]) * t
    lut[p + 3] = a[4] + (b[4] - a[4]) * t
  }
  lutCache.set(key, lut)
  return lut
}

/**
 * 锚点归一：值 → [0,1]。levels 是**升序**的锚点值，色轴在锚点之间等分。
 * 例：levels = [0, 0.1, 0.5, 1, 2, 4, 8, 16, 32, 64]（mm/h）
 *     → 0.05 落在第 0 段中点 → u = 0.5/9；32 → u = 8/9。
 * ★ 这是「值轴不等距、色轴等距」的实现，也是气象色标与线性拉伸的全部区别。
 * 落在最低锚点以下 → 0；最高以上 → 1（夹紧，不外推）。
 */
export function levelNorm(v, levels) {
  const n = levels.length;
  if (!(n > 1)) return 0
  if (!(v > levels[0])) return 0
  if (v >= levels[n - 1]) return 1
  let k = 0
  while (k < n - 2 && v >= levels[k + 1]) k++
  const a = levels[k], b = levels[k + 1]
  const t = b > a ? (v - a) / (b - a) : 0
  return (k + t) / (n - 1)
}

/** 锚点档位的图例刻度：色轴等距，故位置就是 i/(n−1)，标签是锚点值本身 */
export function levelTicks(levels) {
  const n = levels.length
  return levels.map((v, i) => ({ u: n > 1 ? i / (n - 1) : 0, v }))
}
